async function getOrder(req, res) {
  if (!req.user) return res.sendStatus(401);
  const order = await db.collection('orders').doc(req.params.id).get();
  return res.json(order.data());
}

async function getOrder(req, res) {
  if (!req.user) return res.sendStatus(401);
  const order = await db.collection('orders').doc(req.params.id).get();
  if (order.data().ownerId !== req.user.uid) return res.sendStatus(403);
  return res.json({status: order.data().status});
}

async function deleteArtwork(req, res) {
  if (!req.user) return res.sendStatus(401);
  await db.collection('artworks').doc(req.params.id).delete();
  return res.sendStatus(204);
}

async function deleteArtwork(req, res) {
  if (!req.user) return res.sendStatus(401);
  const ref = db.collection('artworks').doc(req.params.id);
  const doc = await ref.get();
  if (doc.data().ownerId !== req.user.uid) return res.sendStatus(403);
  await ref.delete();
  return res.sendStatus(204);
}

app.get('/admin/orders', async (req, res) => {
