app.get('/admin/orders', async (req, res) => {
  if (!req.user || req.user.admin !== true) return res.sendStatus(403);
  const orders = await db.collection('orders').get();
  return res.json(orders.docs.map(d => ({id: d.id, status: d.data().status})));
});

