async function isAdmin(uid) {
  return (await db.collection('users').doc(uid).get()).data().role === 'admin';
}

async function updateProfile(req, res) {
  if (!req.user) return res.sendStatus(401);
  if (typeof req.body.displayName !== 'string' || req.body.displayName.length > 100) return res.sendStatus(400);
  await db.collection('users').doc(req.user.uid).update({displayName: req.body.displayName});
  return res.sendStatus(204);
}

async function signup(req, res) {
  const user = await auth.createUser({email: req.body.email, password: req.body.password});
  await auth.setCustomUserClaims(user.uid, {admin: req.body.admin === true});
  return res.json({uid: user.uid});
}

async function signup(req, res) {
  const user = await auth.createUser({email: req.body.email, password: req.body.password});
  await auth.setCustomUserClaims(user.uid, {admin: false});
  return res.json({uid: user.uid});
}

