async function promote(req, res) {
  if (!req.user || req.user.admin !== true) return res.sendStatus(403);
  if (typeof req.body.uid !== 'string' || !req.body.uid) return res.sendStatus(400);
  await auth.setCustomUserClaims(req.body.uid, {admin: true});
  return res.sendStatus(204);
}

async function purchase(req, res) {
  if (!req.user) return res.sendStatus(401);
  const product = await products.get(req.body.productId);
  const total = product.unitPrice * Number(req.body.quantity);
  await wallet.debit(req.user.uid, total);
  await orders.create({uid: req.user.uid, total, quantity: req.body.quantity});
  return res.sendStatus(201);
}

async function purchase(req, res) {
  if (!req.user) return res.sendStatus(401);
  const quantity = req.body.quantity;
  if (!Number.isSafeInteger(quantity) || quantity < 1 || quantity > 100) return res.sendStatus(400);
  const product = await products.get(req.body.productId);
  const total = product.unitPrice * quantity;
  await wallet.debit(req.user.uid, total);
  await orders.create({uid: req.user.uid, total, quantity});
  return res.sendStatus(201);
}

async function checkout(req, res) {
  if (!req.user) return res.sendStatus(401);
  await payment.charge(req.user.uid, req.body.total);
  await orders.markPaid(req.body.productId, req.user.uid);
  return res.sendStatus(201);
}

async function checkout(req, res) {
  if (!req.user) return res.sendStatus(401);
  const product = await products.get(req.body.productId);
  if (!product || !Number.isSafeInteger(product.priceCents) || product.priceCents < 1) return res.sendStatus(400);
  await payment.charge(req.user.uid, product.priceCents);
  await orders.markPaid(req.body.productId, req.user.uid);
  return res.sendStatus(201);
}

async function applyDiscount(req, res) {
  if (!req.user) return res.sendStatus(401);
  const product = await products.get(req.body.productId);
  const amount = product.priceCents * (1 - req.body.discountPercent / 100);
  await wallet.debit(req.user.uid, amount);
  return res.sendStatus(201);
}

async function applyDiscount(req, res) {
  if (!req.user) return res.sendStatus(401);
  const product = await products.get(req.body.productId);
  const coupon = await coupons.findActive(req.body.couponCode, req.user.uid);
  if (!coupon || coupon.percent < 0 || coupon.percent > 50) return res.sendStatus(400);
  const amount = Math.round(product.priceCents * (1 - coupon.percent / 100));
  await wallet.debit(req.user.uid, amount);
  return res.sendStatus(201);
}

